import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { fetchMachinesForCurrentUser } from '../services/api';

export default function DashboardPage() {
  const navigate = useNavigate();
  const { user, isAuthenticated } = useAuth();
  const [machine, setMachine] = useState(null);
  const [loading, setLoading] = useState(false);
  const [notFound, setNotFound] = useState(false);

  // Активная вкладка: 'info' (Общая информация), 'TO', 'claims'
  const [activeTab, setActiveTab] = useState('info');

  // Данные машин (для раздела "Общая информация")
  const [machines, setMachines] = useState([]);
  const [filters, setFilters] = useState({
    date_shipment_from_factory: '',
    model_machine: '',
    model_engine: '',
    model_transmission: '',
    model_controlled_bridge: '',
    model_driving_bridge: '',
    serial_number_machine: '',
  });

  // Сортировка по умолчанию - по date_shipment_from_factory (возрастание)
  const [sortKey, setSortKey] = useState('date_shipment_from_factory');
  const [sortAsc, setSortAsc] = useState(true);

  // Имя пользователя для отображения (из user)
  const userName = user?.customer?.name
    || user?.service_company?.name
    //|| 'Пользователь';

  // Загрузка данных машин при переходе во вкладку "Общая информация"
  useEffect(() => {
  if (activeTab !== 'info') return;

  const loadMachines = async () => {
    try {
      const data = await fetchMachinesForCurrentUser();
      if (Array.isArray(data)) {
        setMachines(data);
      } else {
        setMachines([]);
      }
    } catch {
      setNotFound(true);
    } finally {
      setLoading(false);
    }
  };

  loadMachines();
  }, [activeTab]);
}
